from contextlib import contextmanager
from inspect import currentframe
from logging import Logger
from os import path

from ta_logcollector.logger import get_net_logger
from ta_logcollector.settings import SERVER_HOST

logger = Logger("LC")


def start_iphy_plugin(log_host, log_port, iphy_config, log_dir):
    from .iphy import iphy

    iphy_obj = iphy(log_host, log_port, iphy_config, log_dir=log_dir)
    iphy_obj.start()
    return iphy_obj


def start_cus_plugin(log_host, log_port, cus_config, log_dir):
    from .cus import cus

    logger.debug("start_cus_plugin: {}".format(cus_config))
    cus_obj = cus(log_host, log_port, cus_config, log_dir=log_dir)
    cus_obj.start()
    return cus_obj


def start(log_host, log_port, sims_objects, **kwargs):
    # type: (str, int, dict, dict) -> dict
    """Method should configure UE Simulators require an activation."""
    logger.info("Inside {} before start".format(path.basename(__file__)))
    log_dir = kwargs.pop("log_dir")
    for sim in ["iphy", "cus", "airphone"]:
        if kwargs.get(sim, False):
            sim_func = globals()["start_{}_plugin".format(sim)]
            sims_objects[sim] = sim_func(log_host, log_port, kwargs[sim], log_dir)
            logger.debug("Started plugin for {}, sim_func = {}".format(sim, sim_func))
    logger.info("Inside {} after start".format(path.basename(__file__)))
    return sims_objects


def stop(sims_objects):
    # type: (dict) -> None
    """Method should collect and store all UE simulator related logs."""
    logger.info("Inside {} before stop".format(path.basename(__file__)))
    for sim, sim_obj in sims_objects.items():
        logger.debug("Stopping {}".format(sim))
        sim_obj.stop()
        logger.debug("Stopped {}".format(sim))
    logger.info("Inside {} after stop".format(path.basename(__file__)))


@contextmanager
def ue_sim(log_host, log_port, **kwargs):
    # type: (str, int, dict) -> None
    """
    Plugin for UE Simulator.
    Supports: IPhy, CUS, RTG and AirPhone.

    :param log_host: IP address of logger host
    :param log_port: port of logger host
    """
    global logger
    logger = get_net_logger(log_host, log_port, "{}_{}".format(currentframe().f_code.co_name, SERVER_HOST))
    sims_objects = {}
    logger.debug("kwargs={}".format(kwargs))
    try:
        start(log_host, log_port, sims_objects, **kwargs)
        yield
    except Exception as err:
        logger.debug(err, exc_info=True)
    finally:
        stop(sims_objects)
